using System.Buffers;
using System.Reflection;
using HyperPdf.Core.Licences;

namespace HyperPdf.ViewModels.Services;

/// <summary>
/// Reads the third-party notices that the build embeds in the app (<c>licenses/notices/HyperPdf.App.md</c>,
/// generated by <c>scripts/GenerateThirdPartyNotices.cs</c>). Each application lifetime reads the file once.
/// </summary>
internal sealed class LicenceNotices
{
    /// <summary>The name of the embedded resource.</summary>
    internal const string ResourceName = "HyperPdf.ThirdPartyNotices.md";

    /// <summary>The assembly that embeds the notices.</summary>
    private readonly Assembly _assembly;

    /// <summary>The notices once read.</summary>
    private NoticeDocument? _document;

    /// <summary>Initializes a new instance of the <see cref="LicenceNotices"/> class.</summary>
    /// <param name="assembly">The assembly that embeds the notices.</param>
    internal LicenceNotices(Assembly assembly)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        _assembly = assembly;
    }

    /// <summary>Gets the notices embedded in the app.</summary>
    /// <returns>The notices; empty when the resource is missing.</returns>
    internal NoticeDocument Load() => Volatile.Read(ref _document) ?? Read();

    /// <summary>Reads the embedded text and publishes the parsed notices.</summary>
    /// <returns>The notices.</returns>
    private NoticeDocument Read()
    {
        using var stream = _assembly.GetManifestResourceStream(ResourceName);
        var document = NoticeDocument.Empty;
        if (stream is not null)
        {
            var length = checked((int)stream.Length);
            var bytes = ArrayPool<byte>.Shared.Rent(length);
            try
            {
                stream.ReadExactly(bytes.AsSpan(0, length));
                document = NoticeDocument.Parse(bytes.AsSpan(0, length));
            }
            finally
            {
                ArrayPool<byte>.Shared.Return(bytes);
            }
        }

        return Interlocked.CompareExchange(ref _document, document, null) ?? document;
    }
}
